result:=ctl||jsonb_build_object('assignment_event_id',(cfg->>'assignment_event_id')::bigint,'claim_event_id',(cfg->>'claim_event_id')::bigint,'clearing_id',q.clearing_id,'input_sha256',q.input_sha256,'probe_id',v.probe_id,'probe_result_sha256',v.result_sha256,'independent_review_event_id',rv_id,'sql_sha256',cfg->>'sql_sha256','new_provider_limit',np,'new_http_limit',nh,'new_tick_limit',nt,'new_source_limit',ns,'new_relation_limit',nr,'current_counters',jsonb_build_object('provider',a.provider_requests,'http',a.http_invocations,'ticks',p.tick_count,'stored_and_reserved_combined',a.stored_bytes+a.reserved_bytes,'relation',used),'disk_available',avail,'remaining_other_work_reserve',avail-greatest(nr-used,0)-greatest(ns-a.stored_bytes-a.reserved_bytes,0)-a.reserved_bytes,'handler_function_sha256',h.function_sha256,'handler_bounds_sha256',encode(sha256(convert_to(nb::text,'UTF8')),'hex'),'cumulative_counters_preserved',true,'original_deadline_preserved',true,'original_target_missed',true,'continuation_authority_event_id',81090,'code_history_clocks_cron_holds_preserved',true,'effects_known',true,'no_manual_source_calls',true);
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details)VALUES('CONTINUATION_MEASURED_ADMISSION_V6',result)RETURNING event_id INTO eid;
SELECT sum(pg_total_relation_size(oid))INTO bytes_after FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m');IF greatest(bytes_after-bytes_before,0)+(cfg->>'prior_growth_charge')::bigint>33554432 THEN RAISE EXCEPTION'V9CAP_WHOLE_UNIT_GROWTH';END IF;
PERFORM set_config('resource_v9.capacity_result',(result||jsonb_build_object('admission_event_id',eid,'production_growth',greatest(bytes_after-bytes_before,0)))::text,true);
END$capacity$;
